<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import type { GameCatalog, NarrativeOption, NarrativeProposalCandidate } from '../api/types'
import { listGames, loadGameCatalog } from '../api/client'
import { useGameStore } from '../stores/game'
import NarrativeTurn from '../components/NarrativeTurn.vue'

type Phase = 'selection' | 'initialization' | 'play' | 'saves'
const route = useRoute(); const router = useRouter(); const store = useGameStore(); const catalog = ref<GameCatalog | null>(null); const saves = ref<Awaited<ReturnType<typeof listGames>>>([]); const phase = ref<Phase>(route.query.phase === 'saves' ? 'saves' : route.params.gameId ? 'play' : 'selection'); const answer = ref(''); const error = ref(''); const busy = ref(false)
const selection = reactive({ worldId: '', engineId: null as string | null })
const currentWorld = computed(() => store.game?.world)
async function loadCatalog() { catalog.value = await loadGameCatalog(); selection.worldId ||= catalog.value.worlds[0]?.id || ''; }
async function begin() { error.value = ''; busy.value = true; try { await store.startInitialization(selection); phase.value = 'initialization' } catch (cause) { error.value = cause instanceof Error ? cause.message : '无法开始建局。' } finally { busy.value = false } }
async function submitAnswer() { if (!answer.value.trim()) return; error.value = ''; try { const next = await store.answerInitialization(answer.value); answer.value = ''; if (next?.done) error.value = '' } catch (cause) { error.value = cause instanceof Error ? cause.message : '答案未通过服务器校验。' } }
async function answerOption(value: string) { answer.value = value; await submitAnswer() }
async function finalize() { try { const created = await store.finalizeInitialization(); if (!created) return; phase.value = 'play'; await router.replace(`/game/${encodeURIComponent(created.gameId)}`) } catch (cause) { error.value = cause instanceof Error ? cause.message : '创建游戏失败。' } }
/** 将判别联合值格式化为可读文本。 */
/** @param value 服务端返回的类型化值 */
function displayValue(value: { type: string; value: string | number | boolean }): string { return value.type === 'text' ? String(value.value) : `${value.type}: ${String(value.value)}` }
async function loadSaved(gameId: string) { busy.value = true; try { await store.load(gameId); phase.value = 'play'; await router.replace(`/game/${encodeURIComponent(gameId)}`) } catch (cause) { error.value = cause instanceof Error ? cause.message : '无法加载存档。' } finally { busy.value = false } }
function choose(option: NarrativeOption) { void store.chooseOption(option, '') }
function applyProposal(proposal: NarrativeProposalCandidate, index: number) { void store.applyProposal(proposal, index) }
onMounted(async () => { try { if (phase.value === 'play' && route.params.gameId) await loadSaved(String(route.params.gameId)); else if (phase.value === 'saves') saves.value = await listGames(); else await loadCatalog() } catch (cause) { error.value = cause instanceof Error ? cause.message : '页面数据加载失败。' } })
</script>
<template>
  <section v-if="phase === 'selection'" class="page-content game-flow"><div class="section-heading"><div><p class="eyebrow">NEW GAME / 01</p><h1>选择你的故事</h1><p class="lede">世界书提供内容，游戏引擎提供可选规则。纯叙事模式也可以开始。</p></div><button class="quiet-button" type="button" @click="router.push('/')">返回首页</button></div><div class="selection-grid form-panel"><label class="field"><span>世界书</span><select v-model="selection.worldId"><option v-for="world in catalog?.worlds || []" :key="world.id" :value="world.id">{{ world.name }}</option></select></label><label class="field"><span>游戏引擎</span><select v-model="selection.engineId"><option :value="null">纯叙事（无引擎）</option><option v-for="engine in catalog?.engines || []" :key="engine.id" :value="engine.id">{{ engine.displayName }}</option></select></label><button class="primary-button confirm-selection" type="button" :disabled="busy || !selection.worldId" @click="begin">{{ busy ? '准备中…' : '确认并开始问答' }} <span>→</span></button></div><p v-if="error" class="form-error" role="alert">{{ error }}</p></section>
  <section v-else-if="phase === 'initialization'" class="page-content game-flow init-chat"><div class="section-heading"><div><p class="eyebrow">INITIALIZATION / 02</p><h1>和 GM 确认开局</h1><p class="lede">在下方与 GM 对话，完成开局资料的确认。</p></div><button class="quiet-button" type="button" @click="phase = 'selection'">重新选择</button></div><div class="chat-log" aria-live="polite"><div v-for="msg in store.initializationHistory" :key="msg.id" class="chat-row" :class="msg.role"><div class="chat-bubble"><span class="chat-speaker">{{ msg.role === 'gm' ? 'GM' : '你' }}</span><p class="chat-text">{{ msg.text }}</p><div v-if="msg.role === 'gm' && msg.parseCandidates?.length" class="chat-parse"><span v-for="(candidate, index) in msg.parseCandidates" :key="`${candidate.fieldId}-${index}`" class="parse-tag">{{ candidate.fieldId }} = {{ displayValue(candidate.value) }}</span></div></div></div><div v-if="store.initializationBusy" class="chat-row gm"><div class="chat-bubble typing"><span class="loader small" />GM 正在思考…</div></div></div><div v-if="store.initializationTurn?.question?.options?.length" class="chip-row"><button v-for="option in store.initializationTurn.question.options" :key="option" class="choice-chip" type="button" :disabled="store.initializationBusy" @click="answerOption(option)">{{ option }}</button></div><div class="free-input chat-composer"><input v-model="answer" placeholder="输入你的回答" @keyup.enter="submitAnswer" /><button v-if="store.initializationTurn?.done" class="secondary-button" type="button" :disabled="store.initializationBusy" @click="finalize">确认并创建游戏</button><button v-else class="primary-button" type="button" :disabled="store.initializationBusy || !answer.trim()" @click="submitAnswer">{{ store.initializationBusy ? '发送中…' : '回答' }}</button></div><p v-if="error || store.error" class="form-error" role="alert">{{ error || store.error }}</p></section>
  <section v-else-if="phase === 'saves'" class="page-content game-flow"><div class="section-heading"><div><p class="eyebrow">SAVES</p><h1>加载存档</h1><p class="lede">选择一局继续游玩。</p></div><button class="quiet-button" type="button" @click="router.push('/')">返回首页</button></div><div class="save-list"><button v-for="save in saves" :key="save.gameId" class="save-row" type="button" @click="loadSaved(save.gameId)"><strong>{{ save.gameId }}</strong><span>{{ save.worldId }} · {{ save.engineId || '纯叙事' }}</span><small>第 {{ save.day }} 天 · revision {{ save.revision }} · {{ save.updatedAt }}</small></button><p v-if="!saves.length" class="empty-timeline">暂无存档。</p></div></section>
  <section v-else-if="store.game" class="play-page"><div class="play-header"><div><p class="eyebrow">{{ store.game.rulesetId || 'NARRATIVE' }} / REVISION {{ store.game.revision }}</p><h1>{{ currentWorld?.setting || '当前世界' }}</h1><p>{{ currentWorld?.settingDescription || 'GM 正在等待你的选择。' }}</p></div><div class="play-actions"><button class="quiet-button" type="button" @click="router.push('/')">退出</button><button class="secondary-button" type="button" @click="store.save">保存游戏</button></div></div><div v-if="store.error || store.notice" class="message-bar" :class="{ error: store.error }">{{ store.error || store.notice }}</div><div class="play-layout"><main class="story-column"><div class="story-heading"><h2>GM 对话</h2><span class="revision-badge">第 {{ currentWorld?.day }} 天</span></div><div class="timeline"><article v-for="item in store.events" :key="item.id" class="timeline-item" :class="item.kind"><div class="timeline-marker" /><div class="timeline-copy"><strong>{{ item.title }}</strong><p>{{ item.detail }}</p></div></article></div><NarrativeTurn v-if="store.narration" :turn="store.narration" :acting="store.acting" @choose="choose" @apply-proposal="applyProposal" /><div class="free-input"><input v-model="answer" placeholder="告诉 GM 你要做什么" @keyup.enter="store.speak(answer); answer = ''" /><button class="primary-button" type="button" :disabled="store.acting || !answer.trim()" @click="store.speak(answer); answer = ''">发送</button></div></main><aside class="status-column"><section class="status-panel"><p class="panel-kicker">WORLD STATE</p><h2>当前状态</h2><dl class="world-facts"><div><dt>位置</dt><dd>{{ currentWorld?.location || '未指定' }}</dd></div><div><dt>区域</dt><dd>{{ currentWorld?.currentRegion || '未指定' }}</dd></div><div><dt>天气</dt><dd>{{ currentWorld?.weather || '未指定' }}</dd></div><div><dt>威胁</dt><dd>{{ currentWorld?.threatLevel || '未知' }}</dd></div></dl><div class="quest-callout"><span>主线方向</span><strong>{{ currentWorld?.mainQuest || '尚未确定' }}</strong></div></section><section v-if="store.game.rulesetState" class="status-panel"><p class="panel-kicker">ENGINE STATE</p><pre class="engine-state">{{ JSON.stringify(store.game.rulesetState, null, 2) }}</pre></section></aside></div></section>
</template>
